package com.smarthub.plus;
import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.atomic.AtomicInteger;
public class ChlImportServerTest {
 @Test public void closeAlsoDisconnectsAnAcceptedIdleBrowserSocket()throws Exception{ChlImportServer s=new ChlImportServer(in->"ok");URI u=URI.create(s.loopbackAddress());try(Socket socket=new Socket(u.getHost(),u.getPort())){socket.setSoTimeout(2000);s.close();try{assertEquals(-1,socket.getInputStream().read());}catch(SocketTimeoutException e){fail("Idle socket survived receiver shutdown");}catch(SocketException expected){}}finally{s.close();}}
 private String request(String address,String method,String headers,byte[] body)throws Exception{URI u=URI.create(address);try(Socket socket=new Socket(u.getHost(),u.getPort())){socket.setSoTimeout(4000);OutputStream out=socket.getOutputStream();out.write((method+" "+u.getPath()+" HTTP/1.1\r\nHost: "+u.getAuthority()+"\r\nConnection: close\r\n"+headers+"\r\n").getBytes(StandardCharsets.US_ASCII));out.write(body);out.flush();ByteArrayOutputStream response=new ByteArrayOutputStream();socket.getInputStream().transferTo(response);return response.toString("UTF-8");}}
 @Test public void pageProvidesRealFileUploadAndNoUserFileDownload()throws Exception{try(ChlImportServer s=new ChlImportServer(in->"ok")){String r=request(s.loopbackAddress(),"GET","",new byte[0]);assertTrue(r.startsWith("HTTP/1.1 200"));assertTrue(r.contains("type='file'"));assertTrue(r.contains("application/octet-stream"));assertTrue(r.contains("no-store"));}}
 @Test public void uploadPreservesUtf8AndInvokesImporter()throws Exception{String value="قناة TV · CHL";byte[] bytes=value.getBytes(StandardCharsets.UTF_8);AtomicInteger calls=new AtomicInteger();try(ChlImportServer s=new ChlImportServer(in->{ByteArrayOutputStream out=new ByteArrayOutputStream();in.transferTo(out);assertEquals(value,out.toString("UTF-8"));calls.incrementAndGet();return "Imported";})){String origin="http://"+URI.create(s.loopbackAddress()).getAuthority();String r=request(s.loopbackAddress(),"POST","Origin: "+origin+"\r\nContent-Type: application/octet-stream\r\nContent-Length: "+bytes.length+"\r\n",bytes);assertTrue(r.startsWith("HTTP/1.1 200"));assertEquals(1,calls.get());}}
 @Test public void wrongTokenOrForeignOriginCannotImport()throws Exception{AtomicInteger calls=new AtomicInteger();try(ChlImportServer s=new ChlImportServer(in->{calls.incrementAndGet();return "ok";})){assertTrue(request(s.loopbackAddress()+"bad","GET","",new byte[0]).startsWith("HTTP/1.1 404"));assertTrue(request(s.loopbackAddress(),"POST","Origin: http://foreign.test\r\nContent-Length: 1\r\nContent-Type: application/octet-stream\r\n",new byte[]{1}).startsWith("HTTP/1.1 403"));assertEquals(0,calls.get());}}
 @Test public void oversizedOrUnexpectedContentDoesNotReachImporter()throws Exception{AtomicInteger calls=new AtomicInteger();try(ChlImportServer s=new ChlImportServer(in->{calls.incrementAndGet();return "ok";})){for(String headers:new String[]{"Content-Length: 16777217\r\nContent-Type: application/octet-stream\r\n","Content-Length: 1\r\nContent-Type: text/plain\r\n"})assertTrue(request(s.loopbackAddress(),"POST",headers,new byte[0]).startsWith("HTTP/1.1 413"));assertEquals(0,calls.get());}}
}
